import hashlib, os

def _stretch(salt, pw):
    data = (salt + pw).encode()
    for _ in range(2000):
        data = hashlib.sha256(data + salt.encode()).digest()
    return data.hex()

def make(pw):
    salt = os.urandom(8).hex()
    return salt + "$" + _stretch(salt, pw)

def check(pw, stored):
    salt, h = stored.split("$", 1)
    return _stretch(salt, pw) == h
